import{_ as o,l as i,o as e,c as s,v as t,p as n,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"OCD 与穆勒矩阵","description":"","frontmatter":{"title":"OCD 与穆勒矩阵","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ocd-mueller.md","filePath":"litho/ocd-mueller.md","lastUpdated":1789023840000}'),h={name:"litho/ocd-mueller.md"};function C(D,a,c,m,A,_){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="ocd-与穆勒矩阵" tabindex="-1">OCD 与穆勒矩阵 <a class="header-anchor" href="#ocd-与穆勒矩阵" aria-label="Permalink to &quot;OCD 与穆勒矩阵&quot;">​</a></h1><div class="epigraph"><p>常规散射测量读的是强度或椭偏谱；穆勒矩阵把偏振变换全记下来，剖面的各向异性和退偏才进模型，而不是被平均进一个标量 CD。</p><footer>—— 据光学计量通称与 KLA 对散射测量 / 椭偏 OCD 的公开原理整理</footer></div><p><a href="/litho/cd-sem-shrink">上一课</a>（SEM 收缩与充电）。把 CD 分成 SEM 局部与 OCD 平均剖面，并停在「光谱拟合堆栈」。缺口是偏振：周期光栅对入射偏振的响应不是一张反射率曲线能写完的，侧壁、沟槽底部圆角、线边缘粗糙都会把偏振态搅乱。本课把 OCD 扩到穆勒矩阵。位置差怎么读，仍留给<a href="/litho/overlay-marks">套刻标记</a>，不要在这里把叠栅位移当成剖面参数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标量或常规椭偏 OCD 用少量偏振通道拟合 CD、侧壁角、膜厚。多解常见：CD 变胖与侧壁变陡可以走同一条谱。二维逻辑、高深宽比沟槽、金属栅的各向异性更重，强度谱的简并变本加厉。缺口是增加独立观测量，而不是再买一台 SEM 去「校准一次永远准」。</p><p>穆勒矩阵 \\(M\\) 把入射斯托克斯矢量映到出射：\\(S_\\mathrm{out}=M S_\\mathrm{in}\\)。\\(4\\times 4\\) 的元素编码二向色、双折射和退偏。光栅的三维剖面正是这些元素的函数。KLA 一类工具的公开原理仍是光谱散射 + 电磁正演 + 回归；穆勒是通道变多，不是换了一种与 OCD 无关的物理。</p><h3 id="退偏不是噪声地板" tabindex="-1">退偏不是噪声地板 <a class="header-anchor" href="#退偏不是噪声地板" aria-label="Permalink to &quot;退偏不是噪声地板&quot;">​</a></h3><p>线边缘粗糙、底层晶粒、光照光斑内的剖面涨落会让出射光部分退偏。常规椭偏若把退偏当模型误差，会把粗糙「拟合」进 CD。穆勒矩阵的退偏块把这部分分开——仍是光斑平均，但不再偷偷改宽度。它替代不了 SEM 看单根线，只是不让平均粗糙污染平均 CD。</p><p><span class="marginnote">穆勒 OCD 仍然看不见随机缺孔。光斑是微米到几十微米，泊松尾部在 SEM 审查里。偏振通道再多，统计量还是平均值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>硬件：极化调制的宽谱入射，测全穆勒或其中对剖面敏感的子集，相对晶圆沟槽取向旋转平面。模型：严格电磁（RCWA 一类）生成库或在线求解，参数含 CD、侧壁、圆角、膜厚、可选各向异性。与 SEM 做相关得到偏置；工艺漂了重做，和上一课完全一样。</p><p>通道多，过拟合也多。参数必须用设计与工艺先验钉住：随意放开底部 CD 与顶 CD 和膜厚，穆勒也会给一套「很美」的假剖面。库要按叠层分，换 BARC / EUV 底层等于换库。光照方位相对栅取向至少要声明；旋转 90° 等于换一套各向异性，不能把水平和垂直金属垫混进同一个回归。</p><h3 id="进控制环的仍然是平均量" tabindex="-1">进控制环的仍然是平均量 <a class="header-anchor" href="#进控制环的仍然是平均量" aria-label="Permalink to &quot;进控制环的仍然是平均量&quot;">​</a></h3><p>APC 要的是稳定、可重复的平均 CD 或侧壁，用穆勒是为了让这个平均数少被简并绑架。场内 CDU 指纹仍靠垫的空间采样，穆勒不自动给出整场图。形貌（侧壁角）比强度 OCD 更信一点，仍要声明模型。</p><p>换照明或换节距等于换衍射级权重，库要按产品层分，不能一张「通用金属库」打天下。</p>',15)),(e(),n(E,null,{default:r(()=>[p(l,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E5%B0%84%E5%81%8F%E6%8C%AF%20%2F%20%E5%85%89%E8%B0%B1%22%5D%20--%3E%20MM%5B%22%E7%A9%86%E5%8B%92%E7%9F%A9%E9%98%B5%20M%22%5D%0A%20%20MM%20--%3E%20RCWA%5B%22%E7%94%B5%E7%A3%81%E6%AD%A3%E6%BC%94%22%5D%0A%20%20RCWA%20--%3E%20PROF%5B%22%E5%B9%B3%E5%9D%87%E5%89%96%E9%9D%A2%3A%20CD%20%2F%20%E4%BE%A7%E5%A3%81%22%5D%0A%20%20DEP%5B%22%E9%80%80%E5%81%8F%20%2F%20%E5%90%84%E5%90%91%E5%BC%82%E6%80%A7%22%5D%20--%3E%20MM%0A%20%20PROF%20--%3E%20APC%5B%22%E5%89%82%E9%87%8F%E6%88%96%E5%88%BB%E8%9A%80%E5%8F%8D%E9%A6%88%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>周期结构的衍射级携带偏振相关相位。梯形侧壁让有效光程沿深度变，表现为椭偏角随波长转动；底部未刻尽或底脚则改零级与高阶的能量比。穆勒非对角元对「左右侧壁不对称」敏感——这正是刻蚀风和套刻标记不对称的亲戚，但本课拟合的是 CD 剖面，不是层间位移。把不对称全写进 overlay，会把 OCD 能看见的刻蚀风漏掉。</p><p>材料色散误差仍然是一阶：金属在紫外的光学常数不准，穆勒元素集体偏，回归把债推给 CD。光学常数表过期时，看起来像 EL 变了，其实是库废了。上一课已经警告过，偏振通道不能豁免。</p><p><span class="marginnote">不要把 scatterometry 理解成显微镜看线宽，也不要把穆勒理解成「更贵的显微镜」。它是远场衍射反问题，对节距和材料色散敏感。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲某型号的通道数或未公开的库算法，也不把穆勒写成可以替代套刻或缺陷检测。非周期热点、SRAM 二维拐角，周期假设失败，还是 SEM。掩模上的 OCD 是另一条链。</p><p>后课默认：说到 OCD，可以是强度/椭偏，也可以是穆勒扩展；简并要用偏振信息减，不能靠把 SEM 相关做一次就宣布物理相等。位置计量从标记课重新起笔。</p><p><span class="marginnote">报 OCD CD 必须写：穆勒还是常规椭偏、库版本、叠层、与 SEM 的偏置日期。通道升级而库未升级，等于换尺子不换刻度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>穆勒矩阵把 OCD 从少数偏振通道扩成完整偏振变换。</li><li>目的是减轻 CD–侧壁简并、分开退偏，不是看见单根 LER。</li><li>仍是光斑平均；缺孔与热点仍归 SEM。</li><li>换底层或色散表必须重建库。</li><li>出处：光学散射计量通称；KLA 对 OCD / 光谱椭偏的公开原理。</li></ul>',10))])}const B=o(h,[["render",C]]);export{f as __pageData,B as default};
